for (const key of [
      'setMicrophoneEnabled',
      'releasePushToTalkKey',
      'resetSession',
    ])
      wrap(input, key, notify);

for (const key of [
          'onAudioStart',
          'onAudioEnd',
          'onAudioDiscard',
          'onDrain',
        ]) {
          const callback = options?.[key];
          decorated[key] = function (...values) {
            const result =
              typeof callback === 'function'
                ? Reflect.apply(
                    callback,
                    this === decorated ? options : this,
                    values,
                  )
                : undefined;
            if (
              !dead &&
              stamp === version &&
              audio === current &&
              controller.audio === current
            ) {
              if (
                key === 'onAudioStart' &&
                options.pushToTalk &&
                controller.captureOwner?.admitted
              )
                inputBusy = true;
              if (key === 'onAudioEnd' || key === 'onAudioDiscard')
                inputBusy = false;
              notify();
            }
            return result;
          };
        }

for (const key of ['play', 'clearPlayback', 'close'])
            wrap(
              current,
              key,
              () => {
                if (audio !== current) return;
                if (key === 'close') {
                  retireAudio();
                  inputBusy = false;
                }
                if (controller.audio === current) notify();
              },
              audioRestores,
            );

for (const match of html.matchAll(/<(\/?)([a-z][\w-]*)\b([^>]*)>/gi)) {
      if (match[1]) {
        if (stack.length > 1) stack.pop();
        continue;
      }
      const node = new Element(this.ownerDocument, match[2]);
      for (const attr of match[3].matchAll(/([^\s=\/]+)(?:="([^"]*)")?/g))
        node.setAttribute(attr[1], attr[2] ?? '');
      stack.at(-1).appendChild(node);
      if (!voids.has(node.tagName)) stack.push(node);
    }
